package at.foama.wien;
import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.android.controller.ActivityController;
import org.json.*;import android.view.*;import android.widget.*;import android.graphics.*;import android.os.Looper;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="w227dp-h227dp-round-xhdpi") @LooperMode(LooperMode.Mode.PAUSED)
public class JourneyStoreTest {
 @Before public void clean(){RuntimeEnvironment.getApplication().getSharedPreferences("foama",0).edit().clear().commit();}
 private JSONObject fixture()throws Exception{return new JSONObject(new String(Files.readAllBytes(Paths.get("tests/fixtures/transfer-routes-webcrypto.json")),StandardCharsets.UTF_8));}
 private JSONObject route()throws Exception{return fixture().getJSONObject("value").getJSONArray("journeys").getJSONObject(0);}
 private Repo repo(){return new Repo(RuntimeEnvironment.getApplication());}
 @Test public void webV2CiphertextDecryptsOnWatchAndNativeCiphertextIsAvailableToVerifyWithWebCrypto()throws Exception{
  JSONObject f=fixture();TransferManager manager=new TransferManager(BuildConfig.FOAMA_BASE_URL);System.arraycopy(TransferManager.dec(f.getString("key")),0,manager.secret,0,32);assertEquals(f.getJSONObject("value").toString(),manager.decrypt(f.getJSONObject("packet")).toString());JSONObject result=new JSONObject().put("key",f.getString("key")).put("value",f.getJSONObject("value")).put("packet",manager.encrypt(f.getJSONObject("value")));Files.write(Paths.get(".local/transfer-routes-java-packet.json"),result.toString().getBytes(StandardCharsets.UTF_8));manager.destroy();
 }
 @Test public void previewDoesNotSaveAndExplicitMergePreservesOldStationFavoritesAcrossRestart()throws Exception{
  Repo repo=repo();repo.toggleFavorite(repo.stops.get(0),"U1","Test");TransferManager.Preview preview=TransferManager.preview(fixture().getJSONObject("value"),repo);assertEquals(1,preview.journeys.length());assertEquals(0,repo.journeys.all().length());assertEquals(1,repo.favorites.size());repo.mergeTransfer(preview);Repo restarted=repo();assertEquals(1,restarted.journeys.all().length());assertEquals("U1",restarted.favorites.get(0).route);assertEquals(2,restarted.favorites.size());
  TransferManager.Preview again=TransferManager.preview(fixture().getJSONObject("value"),restarted);assertEquals(0,again.journeys.length());assertEquals(0,again.favorites.length());assertEquals(2,again.duplicates);
 }
 @Test public void sanitizerNeverStoresHistoricalTimesGeometryOrDynamicGpsCoordinates()throws Exception{
  JSONObject raw=route();raw.put("startTime","2020-01-01").put("private","PRIVATE");raw.getJSONObject("from").put("lat",48.123456).put("lon",16.123456);JSONObject leg=raw.getJSONArray("legs").getJSONObject(0);leg.put("geometry","PRIVATE_GEOMETRY").put("quality","live");leg.getJSONObject("from").put("lat",48.123456);String safe=JourneyStore.sanitize(raw).toString();for(String forbidden:new String[]{"48.123456","PRIVATE","startTime","geometry","quality"})assertFalse(forbidden,safe.contains(forbidden));assertTrue(safe.contains("Dein Standort"));
 }
 @Test public void malformedCollectionsRejectBeforeEitherTypeOfFavoriteChangesAndIdCollisionsAreRepaired()throws Exception{
  Repo repo=repo();JSONObject initial=route();repo.journeys.merge(new JSONArray().put(initial));JSONObject duplicate=route().put("name","New name").put("id","different");assertEquals(1,repo.journeys.preview(new JSONArray().put(duplicate)).duplicates);assertEquals(initial.optString("name"),repo.journeys.all().getJSONObject(0).optString("name"));
  JSONObject other=route();other.getJSONObject("to").put("lat",48.3);repo.journeys.merge(new JSONArray().put(other));assertNotEquals(repo.journeys.all().getJSONObject(0).optString("id"),repo.journeys.all().getJSONObject(1).optString("id"));
  JSONObject malformed=fixture().getJSONObject("value");malformed.getJSONArray("journeys").put(new JSONObject());try{TransferManager.preview(malformed,repo);fail("Invalid collection accepted");}catch(IllegalArgumentException expected){}assertTrue(repo.favorites.isEmpty());assertEquals(2,repo.journeys.all().length());
  try{JourneyStore.sanitize(route().put("savedAt","123"));fail("Invalid date type");}catch(IllegalArgumentException expected){}
 }
 @Test public void routeCapacityIsBoundedWithoutDeletingAnyExistingRoute()throws Exception{
  Repo repo=repo();JSONArray many=new JSONArray();for(int i=0;i<30;i++){JSONObject route=route().put("id","route-"+i);route.getJSONObject("to").put("lon",16.3+i*.001);many.put(route);}assertEquals(30,repo.journeys.merge(many));JSONObject another=route().put("id","overflow");another.getJSONObject("to").put("lon",17);try{repo.journeys.merge(new JSONArray().put(another));fail("Too many routes");}catch(IllegalArgumentException expected){}assertEquals(30,repo.journeys.all().length());repo.journeys.remove("route-0");assertEquals(29,repo.journeys.all().length());
 }
 private Repo.Departure departure(Repo repo,JSONObject leg,int minutes){Repo.Departure d=new Repo.Departure();d.stopKey=leg.optJSONObject("from").optString("stopId");Repo.Stop stop=repo.findStop(d.stopKey);d.rbl=stop.rbl.get(0);d.route=leg.optString("route");d.mode=leg.optString("mode");d.towards=leg.optString("towards");d.when=System.currentTimeMillis()+minutes*60000;d.fetchedAt=System.currentTimeMillis();d.quality="Live";return d;}
 @Test public void currentTimesRequireExactStationLineModeDirectionAndFreshSuccessfulData()throws Exception{
  Repo repo=repo();JSONObject leg=JourneyStore.boardings(route()).get(0);Repo.Departure good=departure(repo,leg,4);repo.departures.add(good);Repo.Departure wrong=departure(repo,leg,2);wrong.towards="Wrong";repo.departures.add(wrong);Repo.Departure stale=departure(repo,leg,3);stale.fetchedAt-=120000;repo.departures.add(stale);assertEquals(Collections.singletonList(good),JourneyStore.departures(leg,repo));repo.lastError="offline";assertTrue(JourneyStore.departures(leg,repo).isEmpty());
 }
 @Test public void plannerAndMonitorTerminalAliasesKeepBusTimesAndLateDetailResultsWithoutShowingTheOpposite()throws Exception{
  assertTrue(JourneyStore.directionMatches("Wien Großfeldsiedlung","Großfeldsiedlung U (über Leopoldau S U)"));assertFalse(JourneyStore.directionMatches("Wien Großfeldsiedlung","Floridsdorf S U"));assertFalse(JourneyStore.directionMatches("Großfeldsiedlung (über Leopoldau S U)","Großfeldsiedlung U (über Leopoldauer Platz)"));assertFalse(JourneyStore.directionMatches("Großfeldsiedlung (über Leopoldau S U)","Großfeldsiedlung U"));
  ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).create().start();MainActivity app=controller.get();try{
   Repo.Stop stop=null;for(Repo.Stop s:app.repo.stops)if(s.name.equals("Floridsdorf S U")){stop=s;break;}assertNotNull(stop);
   JSONObject leg=JourneyStore.boardings(route()).get(0).put("route","29B").put("mode","bus").put("towards","Wien Großfeldsiedlung");leg.getJSONObject("from").put("stopId",stop.id).put("name",stop.name);JSONObject route=route().put("legs",new JSONArray().put(leg));app.repo.journeys.merge(new JSONArray().put(route));app.openJourney(route.getString("id"));app.openConnection(stop,"29B","Wien Großfeldsiedlung");assertNotNull(find(app.getWindow().getDecorView(),"—"));
   Repo.Departure good=departure(app.repo,leg,4);good.towards="Großfeldsiedlung U (über Leopoldau S U)";Repo.Departure opposite=departure(app.repo,leg,1);opposite.towards="Floridsdorf S U";app.repo.departures.add(opposite);app.repo.departures.add(good);assertEquals(Collections.singletonList(good),JourneyStore.departures(leg,app.repo));app.renderContent();assertNotNull(find(app.getWindow().getDecorView(),"4′"));assertNull(find(app.getWindow().getDecorView(),"1′"));
  }finally{controller.stop().destroy();}
 }
 private TextView find(View v,String label){if(v instanceof TextView&&((TextView)v).getText().toString().equals(label))return (TextView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){TextView found=find(((ViewGroup)v).getChildAt(i),label);if(found!=null)return found;}return null;}
 private void click(MainActivity app,String label){View target=find(app.getWindow().getDecorView(),label);assertNotNull(label,target);while(!target.isClickable()&&target.getParent() instanceof View)target=(View)target.getParent();assertTrue(target.performClick());}
 @Test @GraphicsMode(GraphicsMode.Mode.NATIVE) public void savedRouteOpensCurrentBoardingsStationDetailAndNextTransferWithCorrectBackAndTopScroll()throws Exception{
  ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).create().start();MainActivity app=controller.get();try{
   JSONObject route=route().put("name","Zur Arbeit");app.repo.journeys.merge(new JSONArray().put(route));List<JSONObject> legs=JourneyStore.boardings(route);app.repo.departures.add(departure(app.repo,legs.get(0),4));app.repo.departures.add(departure(app.repo,legs.get(1),9));app.changeView("fav");assertNotNull(find(app.getWindow().getDecorView(),"Meine Routen"));assertNotNull(find(app.getWindow().getDecorView(),"4′"));click(app,"Zur Arbeit");assertEquals("journey",app.screen);assertNotNull(find(app.getWindow().getDecorView(),"Einstieg 1 von 2"));assertNotNull(find(app.getWindow().getDecorView(),"9′"));
   render(app,".local/wear-journey-227.png",227);assertEquals(0,scroll(app.getWindow().getDecorView()).getScrollY());View departure=find(app.getWindow().getDecorView(),"4′");assertTrue(departure.getWidth()>0);RuntimeEnvironment.setQualifiers("w192dp-h192dp-round-xhdpi");app.openJourney(route.optString("id"));render(app,".local/wear-journey-192.png",192);TextView number=find(app.getWindow().getDecorView(),"4′");android.graphics.Rect bounds=new android.graphics.Rect(0,0,number.getWidth(),number.getHeight());((ViewGroup)app.getWindow().getDecorView()).offsetDescendantRectToMyCoords(number,bounds);assertTrue("First time fits small watch viewport",bounds.bottom/app.getResources().getDisplayMetrics().density<=180);assertTrue(number.getLayout().getLineRight(0)<=number.getWidth()+1);RuntimeEnvironment.setQualifiers("w227dp-h227dp-round-xhdpi");app.openJourney(route.optString("id"));click(app,"Alle Abfahrten");assertEquals("detail",app.screen);java.lang.reflect.Field detail=MainActivity.class.getDeclaredField("detailRoute");detail.setAccessible(true);assertEquals("",detail.get(app));app.navigateBack();assertEquals("journey",app.screen);click(app,"Weiter zum Umstieg");assertEquals(1,app.journeyBoarding);assertNotNull(find(app.getWindow().getDecorView(),"Einstieg 2 von 2"));render(app,".local/wear-journey-transfer-227.png",227);assertEquals(0,scroll(app.getWindow().getDecorView()).getScrollY());app.navigateBack();assertEquals("home",app.screen);assertEquals("fav",app.view);assertFalse(app.isFinishing());app.openJourney(route.optString("id"));click(app,"9′");assertEquals("detail",app.screen);java.lang.reflect.Field focusedStop=MainActivity.class.getDeclaredField("detailStop");focusedStop.setAccessible(true);assertEquals(legs.get(1).getJSONObject("from").getString("stopId"),((Repo.Stop)focusedStop.get(app)).id);assertEquals("U4",detail.get(app));app.navigateBack();assertEquals("journey",app.screen);assertEquals(1,app.journeyBoarding);
  }finally{controller.stop().destroy();}
 }
 private ScrollView scroll(View view){if(view instanceof ScrollView)return (ScrollView)view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){ScrollView result=scroll(((ViewGroup)view).getChildAt(i));if(result!=null)return result;}return null;}
 private void layoutTree(View v){v.forceLayout();if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)layoutTree(((ViewGroup)v).getChildAt(i));}
 private void render(MainActivity app,String file,int dp)throws Exception{View view=app.getWindow().getDecorView();int size=Math.round(dp*app.getResources().getDisplayMetrics().density);layoutTree(view);view.measure(View.MeasureSpec.makeMeasureSpec(size,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(size,View.MeasureSpec.EXACTLY));view.layout(0,0,size,size);org.robolectric.Shadows.shadowOf(Looper.getMainLooper()).idle();Bitmap bitmap=Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888);view.draw(new Canvas(bitmap));try(java.io.FileOutputStream stream=new java.io.FileOutputStream(file)){bitmap.compress(Bitmap.CompressFormat.PNG,100,stream);}bitmap.recycle();}
 private JSONObject alternativeFixture()throws Exception{return new JSONObject(new String(Files.readAllBytes(Paths.get("tests/fixtures/transfer-alternatives-webcrypto.json")),StandardCharsets.UTF_8));}
 @Test public void alternativeTemplatesRemainTimelessAndDynamicGpsIsRemovedFromEveryPath()throws Exception{
  JSONObject input=alternativeFixture().getJSONObject("value").getJSONArray("journeys").getJSONObject(0);JSONObject alt=input.getJSONArray("alternatives").getJSONObject(0);alt.getJSONArray("legs").getJSONObject(0).getJSONObject("from").put("lat",48.123456);alt.getJSONArray("legs").getJSONObject(0).put("startTime","PRIVATE_TIME");JSONObject safe=JourneyStore.sanitize(input);assertEquals(2,JourneyStore.variantCount(safe));assertFalse(safe.toString().contains("48.123456"));assertFalse(safe.toString().contains("PRIVATE_TIME"));assertEquals(1,JourneyStore.commonBoardings(safe,JourneyStore.variant(safe,1)));
 }
 @Test public void transferredAlternativesUpdateTheSameFavoriteWithoutRenamingOrDuplicatingIt()throws Exception{
  Repo repo=repo();JSONObject old=route().put("name","My commute");repo.journeys.merge(new JSONArray().put(old));TransferManager.Preview preview=TransferManager.preview(alternativeFixture().getJSONObject("value"),repo);assertEquals(1,preview.journeys.length());assertEquals(1,repo.journeys.all().length());assertEquals(1,JourneyStore.variantCount(repo.journeys.get(old.getString("id"))));repo.mergeTransfer(preview);Repo restarted=repo();assertEquals(1,restarted.journeys.all().length());assertEquals("My commute",restarted.journeys.get(old.getString("id")).getString("name"));assertEquals(2,JourneyStore.variantCount(restarted.journeys.get(old.getString("id"))));
  JSONObject invalid=route();JSONArray tooMany=new JSONArray();for(int i=0;i<16;i++)tooMany.put(new JSONObject().put("legs",route().getJSONArray("legs")));invalid.put("alternatives",tooMany);try{JourneyStore.sanitize(invalid);fail("Unbounded variants accepted");}catch(IllegalArgumentException expected){}assertEquals(1,restarted.journeys.all().length());
 }
 @Test public void alternativeRouteCiphertextIsCompatibleWithWebCryptoInBothDirections()throws Exception{
  JSONObject f=alternativeFixture();TransferManager manager=new TransferManager(BuildConfig.FOAMA_BASE_URL);System.arraycopy(TransferManager.dec(f.getString("key")),0,manager.secret,0,32);assertEquals(f.getJSONObject("value").toString(),manager.decrypt(f.getJSONObject("packet")).toString());JSONObject result=new JSONObject().put("key",f.getString("key")).put("value",f.getJSONObject("value")).put("packet",manager.encrypt(f.getJSONObject("value")));Files.write(Paths.get(".local/transfer-alternatives-java-packet.json"),result.toString().getBytes(StandardCharsets.UTF_8));manager.destroy();
 }
 @Test public void choosingAnAlternativeFocusesItsTransferInsteadOfTheCommonFirstConnection()throws Exception{
  ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).create().start();MainActivity app=controller.get();try{JSONObject bundle=alternativeFixture().getJSONObject("value").getJSONArray("journeys").getJSONObject(0);app.repo.journeys.merge(new JSONArray().put(bundle));JSONObject option=JourneyStore.variant(bundle,1);app.repo.departures.add(departure(app.repo,JourneyStore.boardings(bundle).get(1),9));app.repo.departures.add(departure(app.repo,JourneyStore.boardings(option).get(1),7));app.openJourney(bundle.getString("id"));click(app,"Alternative Wege (1)");assertEquals("journey-options",app.screen);assertNotNull(find(app.getWindow().getDecorView(),"9′"));assertNotNull(find(app.getWindow().getDecorView(),"7′"));click(app,"Alternative 1");assertEquals("journey",app.screen);assertEquals(1,app.journeyVariant);assertEquals(1,app.journeyBoarding);assertNotNull(find(app.getWindow().getDecorView(),"TEST"));assertNotNull(find(app.getWindow().getDecorView(),"7′"));
  }finally{controller.stop().destroy();}
 }

}
